function getWordsByLevel(level) {
  return WORDS.filter(w => w.level === level);
}

function wordCount(level) {
  return getWordsByLevel(level).length;
}

const WORD_ARTICLES = new Set(["der", "die", "das", "den", "dem", "des", "ein", "eine", "einen", "einem", "zum", "zur", "am", "sich"]);

/**
 * Build a comparable sort key for a word entry: strips leading articles,
 * "(sich)"/parenthetical prefixes and declension suffixes (", -n" etc.) so
 * entries alphabetize by their real headword, e.g. "die Abfahrt" sorts as
 * "abfahrt", not "die".
 */
function wordSortKey(de) {
  let s = de
    .replace(/\(sich\)\s*/i, "")
    .replace(/^\([^)]*\)-?/, "")
    .trim();
  const tokens = s.split(/\s+/);
  while (tokens.length) {
    const t0 = tokens[0].split(/[/,]/)[0].replace(/,$/, "").toLowerCase();
    if (WORD_ARTICLES.has(t0)) {
      tokens.shift();
    } else {
      break;
    }
  }
  const head = (tokens.join(" ") || de).replace(/,.*$/, "");
  return head.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

/** Group a list of word entries into { letter, words }[] buckets, A–Z, each
 *  bucket's words alphabetized by their real headword (see wordSortKey). */
function groupWordsByLetter(words) {
  const byLetter = {};
  words.forEach(w => {
    if (!byLetter[w.letter]) byLetter[w.letter] = [];
    byLetter[w.letter].push(w);
  });
  return Object.keys(byLetter)
    .sort()
    .map(letter => ({
      letter,
      words: byLetter[letter].slice().sort((a, b) => wordSortKey(a.de).localeCompare(wordSortKey(b.de), "de"))
    }));
}

/** Filter words for a level by a free-text query against German or English. */
function searchWords(level, query) {
  const words = getWordsByLevel(level);
  const q = query.trim().toLowerCase();
  if (!q) return words;
  return words.filter(w =>
    w.de.toLowerCase().includes(q) || w.en.toLowerCase().includes(q)
  );
}

/** A small, friendly sample of A1 words for the homepage teaser. */
const FEATURED_WORD_KEYS = ["hallo", "danke", "bitte", "tschüss", "das Wasser", "der Kaffee"];

function getFeaturedWords() {
  return FEATURED_WORD_KEYS
    .map(key => WORDS.find(w => w.de === key))
    .filter(Boolean);
}
